    async Task ClearClientData(){
        if(busy)return;
        try{ClientMaintenance.RequireClientStopped();}catch(Exception ex){Fail(ex);return;}
        if(MessageBox.Show(this,"Сбросить клиентские данные SCUM?\n\nЗакройте игру перед очисткой. Папка %LOCALAPPDATA%\\SCUM будет перемещена в резервную копию, включая настройки, кэш, журналы и одиночные сохранения. При следующем запуске игра создаст новую папку.\n\nФайлы установленной игры и серверный мир не меняются.","Очистка клиента и кэша",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;
        bool couldPlay=play.Enabled;
        await Run("Очищаем клиентские данные…",async()=>{ClientResetResult result=await Task.Run(()=>new ClientMaintenance().Clear());SetStatus(result.changed?"Клиентские данные сброшены":"Клиентские данные уже очищены",result.changed?"Прежняя папка сохранена. Нажмите «Копии», чтобы открыть её.\nТеперь можно повторить запуск SCUM.":"Папка %LOCALAPPDATA%\\SCUM отсутствует. Можно запускать игру.",1);if(result.changed)Log("Резервная копия клиентских данных: "+result.backup);play.Enabled=couldPlay;});
    }
    void SaveFolder(){try{if(!GameDiscovery.IsClient(folder.Input.Text))return;Directory.CreateDirectory(Path.GetDirectoryName(settings));Data.Write(settings,new Settings{root=folder.Input.Text});}catch(Exception ex){Log("Не удалось сохранить путь: "+ex.Message);}}
    async Task DetectGame(bool extended){await Run("Ищем установленную SCUM…",async()=>{
        SetStatus("Ищем установленную SCUM…",extended?"Проверяем библиотеки Steam и локальные диски. Обычно до 15 секунд.":"Проверяем библиотеки Steam на всех дисках.",0);
        GameSearchResult result=await Task.Run(()=>GameDiscovery.Find(extended));
        if(result.paths.Length==0){SetStatus("Клиент SCUM не найден",extended?"Проверены доступные папки. Нажмите «Выбрать…», чтобы указать путь вручную.":"Нажмите «Найти игру» для поиска на дисках или «Выбрать…» для ручного выбора.",2);Log(result.limited?"Поиск ограничен по времени или глубине. Можно указать папку вручную.":"SCUM не найдена в проверенных папках.");return;}
        string selected=result.paths.Length==1?result.paths[0]:SelectGame(result.paths);
        if(selected==null){SetStatus("Выбор папки отменён","Найдено установок: "+result.paths.Length+". Можно повторить поиск или выбрать папку вручную.",0);return;}
        folder.Input.Text=selected;SaveFolder();SetStatus("Клиент SCUM найден","Путь сохранён. Теперь можно проверить обновления сборки.",1);Log("Найден клиент: "+selected);if(result.limited)Log("Поиск на дисках ограничен по времени или глубине; найдены доступные установки.");
    });}
    string SelectGame(string[] paths){using(Form dialog=new Form{Text="Выберите установленную SCUM",ClientSize=new Size(760,285),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=MacTheme.Canvas,ForeColor=MacTheme.Ink,Font=MacTheme.Font(10)}){
        Label prompt=new Label{Text="Найдено несколько клиентов. Выберите нужную установку:",Bounds=new Rectangle(22,18,716,28)};
        ListBox list=new ListBox{Bounds=new Rectangle(22,58,716,155),BackColor=MacTheme.Surface,ForeColor=MacTheme.Ink,BorderStyle=BorderStyle.None,HorizontalScrollbar=true,IntegralHeight=false};list.Items.AddRange(paths);list.SelectedIndex=0;
        MacButton choose=new MacButton{Text="Использовать",Primary=true,Bounds=new Rectangle(444,231,144,36)},cancel=new MacButton{Text="Отмена",Bounds=new Rectangle(600,231,138,36)};
        choose.Click+=(s,e)=>{if(list.SelectedIndex>=0)dialog.DialogResult=DialogResult.OK;};cancel.Click+=(s,e)=>dialog.DialogResult=DialogResult.Cancel;list.DoubleClick+=(s,e)=>{if(list.SelectedIndex>=0)dialog.DialogResult=DialogResult.OK;};
        dialog.Controls.Add(prompt);dialog.Controls.Add(list);dialog.Controls.Add(choose);dialog.Controls.Add(cancel);return dialog.ShowDialog(this)==DialogResult.OK?paths[list.SelectedIndex]:null;
    }}
    bool ChooseFolder(){using(FolderBrowserDialog dialog=new FolderBrowserDialog{Description="Выберите корневую папку SCUM — папку установки из Steam",SelectedPath=Directory.Exists(folder.Input.Text)?folder.Input.Text:"",ShowNewFolderButton=false}){if(dialog.ShowDialog(this)!=DialogResult.OK)return false;folder.Input.Text=dialog.SelectedPath;SaveFolder();return true;}}
    bool EnsureFolder(){if(!String.IsNullOrWhiteSpace(folder.Input.Text))return true;SetStatus("Выберите папку игры","Нажмите «Выбрать…» и укажите установленную SCUM.",2);return ChooseFolder();}
    GameInstall Open(){GameInstall game=GameInstall.Open(folder.Input.Text);Directory.CreateDirectory(Path.GetDirectoryName(settings));Data.Write(settings,new Settings{root=game.Root});return game;}
    UpdateService Service(GameInstall game){return new UpdateService(game,new GitHubSource(),Log);}
    void SetStatus(string title,string text,int state){status.Text=title;details.Text=text;glyph.State=state;glyph.Invalidate();status.ForeColor=state==3?Color.FromArgb(255,131,139):MacTheme.Ink;}
    void Log(string text){if(InvokeRequired){BeginInvoke(new Action<string>(Log),text);return;}emptyLog.Visible=false;output.Visible=true;output.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);if(output.Lines.Length>Math.Max(1,output.Height/Math.Max(1,output.Font.Height)))output.ScrollBars=ScrollBars.Vertical;output.SelectionStart=output.TextLength;output.ScrollToCaret();}
    void Fail(Exception ex){string message=ex is System.Net.WebException?"Не удалось получить релиз GitHub. Проверьте подключение и повторите попытку.":ex.Message;SetStatus("Не удалось завершить операцию",message,3);Log(message);play.Enabled=false;}
    async Task Run(string title,Func<Task> work){if(busy)return;busy=true;SetStatus(title,"Подготовка и проверка файлов. Это может занять некоторое время.",0);progress.Visible=true;check.Enabled=sync.Enabled=rollback.Enabled=browse.Enabled=findGame.Enabled=folder.Enabled=experimental.Enabled=clearClient.Enabled=clientBackups.Enabled=updateLauncher.Enabled=false;play.Enabled=false;try{await work();}catch(Exception ex){Fail(ex);}finally{busy=false;progress.Visible=false;check.Enabled=sync.Enabled=rollback.Enabled=browse.Enabled=findGame.Enabled=folder.Enabled=experimental.Enabled=clearClient.Enabled=clientBackups.Enabled=updateLauncher.Enabled=true;if(closingForUpdate)Close();}}
    protected override void WndProc(ref Message m){const int hit=0x84;if(m.Msg==hit&&WindowState==FormWindowState.Normal){Point p=PointToClient(new Point(unchecked((short)(long)m.LParam),unchecked((short)((long)m.LParam>>16))));int edge=7;bool left=p.X<edge,right=p.X>=Width-edge,top=p.Y<edge,bottom=p.Y>=Height-edge;int value=top?(left?13:right?14:12):bottom?(left?16:right?17:15):left?10:right?11:0;if(value!=0){m.Result=new IntPtr(value);return;}}base.WndProc(ref m);}
    protected override CreateParams CreateParams{get{CreateParams cp=base.CreateParams;cp.ClassStyle|=0x20000;return cp;}}
    public void Snapshot(string file,bool compact=false){capturingSnapshot=true;ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-32000,-32000);if(compact)Size=new Size(920,680);CreateControl();Show();Application.DoEvents();using(Bitmap image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(file,System.Drawing.Imaging.ImageFormat.Png);}Close();}
}
internal static class Program {
    [STAThread] static int Main(string[] args){try{
        if(args.Length==1&&args[0]=="--wait-for-update-test"){System.Threading.Thread.Sleep(5000);return 0;}
        if(args.Length>0&&args[0]=="--self-test")return SelfTests.Run(args.Length>1?args[1]:Path.Combine(Path.GetTempPath(),"SCUMLab-self-test-"+Guid.NewGuid().ToString("N")));
        if(args.Length==4&&args[0]=="--registry-pak"){RegistryPak.Write(args[3],RegistryMerge.Merge(File.ReadAllBytes(args[1]),Data.Read<RegistryDelta>(args[2])));return 0;}
        Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
        if(args.Length==2&&(args[0]=="--screenshot"||args[0]=="--screenshot-compact")){new LauncherForm().Snapshot(args[1],args[0]=="--screenshot-compact");return 0;}Application.Run(new LauncherForm());return 0;
    }catch(Exception ex){if(args.Length>0){Console.Error.WriteLine(ex.ToString());return 1;}MessageBox.Show(ex.Message,"SCUM Lab Launcher",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
